mapper.sql:
deleted_at IS NULL
        AND (title LIKE CONCAT('%',#{keyword},'%') OR question LIKE CONCAT('%',#{keyword},'%') OR keywords LIKE CONCAT('%',#{keyword},'%'))
        AND category_id=#{categoryId}AND status=#{status}

mapper.select:
SELECT 
FROM faq_item f INNER JOIN faq_category c ON c.id=f.category_id
WHERE f.deleted_at IS NULL AND f.status='PUBLISHED' AND c.status='ENABLED'
AND (f.title LIKE CONCAT('%',#{keyword},'%') OR f.question LIKE CONCAT('%',#{keyword},'%') OR f.keywords LIKE CONCAT('%',#{keyword},'%'))
AND f.category_id=#{categoryId}
ORDER BY f.is_top DESC,f.updated_at DESC LIMIT #{offset},#{pageSize}
